"""Self-contained, offline 3D view of measured scans and actual pose graphs."""
import html,os
from s06_common import *
def visual_data(path):
    path=Path(path);g=read(path/'db_graph.json');nodes=g['nodes'];ts=np.array([x['stamp'] for x in nodes]);samples=[]
    files=sorted((path/'mapping_inputs').glob('cloud_*.npz'),key=lambda f:float(f.stem.split('_')[1]))
    for file in files:
        d=np.load(file);t=float(d['t']);a=d['raw'][d['keep']];above=a[:,2]>.2
        ids=np.r_[np.where(above)[0][::max(1,int(above.sum()/250))],np.where(~above)[0][::max(1,int((~above).sum()/150))]];a=a[ids]
        raw=transform(a,d['xyz'],d['q']);node=nodes[int(np.argmin(abs(ts-t)))];r=node['raw'];p=node['optimized'];rotation=Rotation.from_quat(p[3:])*Rotation.from_quat(r[3:]).inv();opt=rotation.apply(raw-np.array(r[:3]))+p[:3]
        samples.extend(np.c_[raw,opt,np.full(len(a),t)].round(3).tolist())
    origin=np.array(yaml.safe_load((BASE/'config/routes/mapping_routes.yaml').read_text())['spawn_survey'][:2]);prior=[]
    for feature in read(BASE/'maps/prior/workspaces.geojson')['features']:
        prior.append(dict(name=feature['properties']['id'],points=np.c_[np.array(feature['geometry']['coordinates'][0])-origin,np.zeros(len(feature['geometry']['coordinates'][0]))].tolist()))
    return dict(points=samples,prior=prior,nodes=[dict(id=x['id'],t=x['stamp'],raw=x['raw'][:3],optimized=x['optimized'][:3]) for x in nodes],links=[dict(source=x['from'],target=x['to'],type=x['type']) for x in g['links'] if x['type'] in [1,2]],metrics=read(path/'metrics.json'),paths=read(path/'plot_data.json'))
def render(out,summary):
    out=Path(out);data={};links={}
    for name,case in summary.get('cases',{}).items():
        path=ROOT/case['path']
        if not (path/'db_graph.json').exists() or not (path/'metrics.json').exists():continue
        data[name]=visual_data(path);links[name]={key:os.path.relpath(path/file,out) for key,file in [('数据库','mapping.db'),('优化点云 PLY','map_optimized_cloud.ply'),('原始里程计点云 PLY','map_odometry_cloud.ply'),('位姿图 JSON','db_graph.json'),('版本契约','map_manifest.json'),('实际相机帧','mapping_inputs/first_camera.png')]}
    checks=''.join(f'<span class="chip">{html.escape(k)} · {html.escape(v)}</span>' for k,v in summary['checks'].items())
    page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>S06 · 三维建图与回环实测</title>
<style>*{box-sizing:border-box}body{margin:0;background:#101b25;color:#e1eaf2;font:15px system-ui,"Noto Sans CJK SC",sans-serif}main{max-width:1420px;margin:auto;padding:28px}h1{margin:8px 0 12px;font-size:30px}h2{font-size:20px}p{color:#b9cad8;line-height:1.7}.eyebrow{letter-spacing:3px;color:#5bd6bb;font-size:12px}.bar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:18px 0}.chip,button,select{padding:9px 13px;border:1px solid #344b60;background:#203345;color:#e2edf4;border-radius:7px}.chip{font-size:13px}input{accent-color:#52d7ba}#time{flex:1;min-width:200px}canvas{width:100%;height:590px;display:block;background:#132433;border:1px solid #34516a;border-radius:14px;touch-action:none}table{width:100%;border-collapse:collapse;font-size:14px}td,th{padding:10px;text-align:left;border-bottom:1px solid #324555}a{color:#74dccc;margin-right:18px}pre{padding:18px;overflow:auto;max-height:350px;background:#182b3b;border-radius:10px}details{margin:20px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.box{padding:20px;border:1px solid #31485b;border-radius:12px}#stats{font-variant-numeric:tabular-nums}.note{font-size:13px;color:#9db5c9}@media(max-width:800px){.grid{grid-template-columns:1fr}main{padding:15px}canvas{height:450px}}</style>
<main><div class="eyebrow">OPTIMIZATION V2 / SENSOR MEASUREMENTS</div><h1>S06 · 三维建图与回环</h1><p id="intro"></p><div class="bar">CHECKS</div>
<div class="bar"><label>实测案例 <select id="case"></select></label><label>显示 <select id="mode"><option value="optimized">回环优化后</option><option value="raw">局部里程计累积</option></select></label><button id="reset">重置视角</button><label><input id="cloud" type="checkbox" checked>点云</label><label><input id="loops" type="checkbox" checked>回环边</label><label><input id="prior" type="checkbox" checked>先验区界</label></div>
<canvas id="map" width="1380" height="590"></canvas><div class="bar"><span>采集时刻</span><input id="time" type="range" min="0" max="100" value="100"><span id="clock"></span></div>
<p class="note">鼠标拖动旋转三维视角，滚轮缩放。点云颜色表示高度；橙色轨迹为里程计，绿色为优化轨迹，红色为真实回环边。虚线区界是公开先验参考，不是雷达建图产物，也不代表 S08 地理配准已完成。增长动画使用每约 5 秒的真实扫描快照；优化显示采用邻近关键帧修正，不是逐帧稠密重建。PLY 保留完整关键帧地图。</p>
<div class="grid"><div class="box"><h2>同一批观测的前后比较</h2><table id="stats"></table></div><div class="box"><h2>数据与质量边界</h2><div id="quality"></div><div id="files" class="bar"></div></div></div>
<details open><summary>首次路线回访事件（间隔 ≥30 s）：同一批历史节点的变化</summary><p id="event"></p><canvas id="eventPlot" width="1380" height="320" style="height:320px"></canvas><p class="note">上方主视图的“原始里程计／最终图”同时包含相邻边细化、重力约束和多次回环的收益。此小图比较首次路线回访前最近保留的图与事件后的图，只取共同历史节点；排除保存后短时重复观测，避免把全部改善归因于一次回环。</p></details><details open><summary>生命周期、停车与错误候选证据</summary><pre id="evidence"></pre></details><details><summary>全部实测检查</summary><pre id="checks"></pre></details>
RVIZ_PREVIEW
<p class="note">人工查看状态：NOT_CHECKED。自动通过不代表已具备 S07 重定位或 S13 自主作业能力。原始弱纹理案例是失败诊断对照，不计为合格建图。</p></main>
<script>const data=DATA, files=FILES, summary=SUMMARY;
const cv=document.getElementById('map'),ctx=cv.getContext('2d'),sel=document.getElementById('case'),mode=document.getElementById('mode'),slider=document.getElementById('time');
document.getElementById('intro').textContent=summary.run_id+' · 自动状态 '+summary.status+' · '+summary.next_step_verdict;
for(const name of Object.keys(data)){let o=document.createElement('option');o.value=name;o.textContent=name;sel.appendChild(o)}
let yaw=-.55,pitch=.86,zoom=1,center=[0,0,0],scale=20,drag=null;
function reset(){let d=data[sel.value];if(!d)return;let p=d.nodes.map(n=>n.optimized),xs=p.map(v=>v[0]),ys=p.map(v=>v[1]);center=[(Math.min(...xs)+Math.max(...xs))/2,(Math.min(...ys)+Math.max(...ys))/2,0];scale=Math.min(cv.width,cv.height)/(Math.max(Math.max(...xs)-Math.min(...xs),Math.max(...ys)-Math.min(...ys),15)+35);yaw=-.55;pitch=.86;zoom=1;draw()}
function project(p){let x=p[0]-center[0],y=p[1]-center[1],z=p[2]-center[2],a=Math.cos(yaw)*x-Math.sin(yaw)*y,b=Math.sin(yaw)*x+Math.cos(yaw)*y;return [cv.width/2+a*scale*zoom,cv.height/2+(b*Math.cos(pitch)-z*Math.sin(pitch))*scale*zoom]}
function line(points,color,width){if(points.length<2)return;ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();points.forEach((p,i)=>{let q=project(p);i?ctx.lineTo(...q):ctx.moveTo(...q)});ctx.stroke()}
function draw(){ctx.clearRect(0,0,cv.width,cv.height);let d=data[sel.value];if(!d){ctx.fillStyle='#b9cad8';ctx.fillText('本轮尚无完整地图，查看错误记录。',40,50);return}
let t=Number(slider.value)/100*Math.max(...d.nodes.map(n=>n.t)),key=mode.value;document.getElementById('clock').textContent=t.toFixed(1)+' 仿真秒';
if(document.getElementById('prior').checked){ctx.setLineDash([6,6]);for(let p of d.prior){line(p.points,'#60798e',1.2);let v=project(p.points[0]);ctx.fillStyle='#b0c5d6';ctx.font='13px system-ui';ctx.fillText('先验 '+p.name,v[0]+8,v[1]-6)}ctx.setLineDash([])}
if(document.getElementById('cloud').checked)for(let p of d.points){if(p[6]>t)continue;let v=key==='raw'?p.slice(0,3):p.slice(3,6),q=project(v);ctx.fillStyle=`hsl(${195-Math.max(0,Math.min(v[2],5))*28} 60% ${v[2]<.2?38:65}%)`;ctx.fillRect(q[0],q[1],v[2]>.2?2.2:1.2,v[2]>.2?2.2:1.2)}
let nodes=d.nodes.filter(n=>n.t<=t),byid=new Map(nodes.map(n=>[n.id,n]));line(nodes.map(n=>n[key]),key==='raw'?'#ffb25a':'#65edb8',2.5);
if(document.getElementById('loops').checked)for(let l of d.links)if(byid.has(l.source)&&byid.has(l.target))line([byid.get(l.source)[key],byid.get(l.target)[key]],'#ff6178',2);
ctx.fillStyle='#c4d7e6';ctx.font='14px system-ui';ctx.fillText(`${key==='raw'?'局部里程计累积':'优化后的地图'} · ${nodes.length}/${d.nodes.length} 关键帧 · 真实扫描`,22,30);ctx.fillText('高度：蓝色 ≈ 地面 → 黄绿色 ≈ 4 m',22,52);let size=10*scale*zoom;ctx.strokeStyle='#d0e0eb';ctx.beginPath();ctx.moveTo(24,cv.height-30);ctx.lineTo(24+size,cv.height-30);ctx.stroke();ctx.fillText('水平投影尺度 10 m',24,cv.height-40);window.s06Rendered=true;}
function update(){let d=data[sel.value];if(!d)return;let m=d.metrics,fmt=x=>Number.isFinite(x)?x.toFixed(3):'N/A';document.getElementById('stats').innerHTML='<tr><th>指标</th><th>优化前</th><th>优化后</th></tr>'+[['轨迹 RMSE / m',m.raw_trajectory.ate_rmse_m,m.optimized_trajectory.ate_rmse_m],['端点误差 / m',m.raw_trajectory.endpoint_m,m.optimized_trajectory.endpoint_m],['回访点云中位误差 / m',m.raw_alignment.median_m,m.optimized_alignment.median_m],['回访点云 P95 / m',m.raw_alignment.p95_m,m.optimized_alignment.p95_m]].map(r=>`<tr><td>${r[0]}</td><td>${fmt(r[1])}</td><td>${fmt(r[2])}</td></tr>`).join('');
document.getElementById('quality').textContent=`${m.nodes} 个关键帧，${m.map_points} 个地图点；视觉回环 ${m.visual_loops} 次，邻近回环 ${m.proximity_loops} 次。动态点抽样剔除 ${(m.dynamic_residue.dynamic_rejection_fraction*100).toFixed(1)}%，仍残留 ${m.dynamic_residue.dynamic_kept} 点。峰值进程内存 ${(m.peak_owned_rss_bytes/1073741824).toFixed(2)} GiB。`;
let box=document.getElementById('files');box.replaceChildren();for(let [name,path] of Object.entries(files[sel.value])){let a=document.createElement('a');a.textContent=name;a.href=path;box.appendChild(a)}
let ev=m.first_loop_event,ec=document.getElementById('eventPlot'),ex=ec.getContext('2d');ex.clearRect(0,0,ec.width,ec.height);if(ev&&ev.available){document.getElementById('event').textContent=`事件 ${ev.before_t.toFixed(1)} → ${ev.after_t.toFixed(1)} s；共同历史节点 ${ev.common_nodes}；ATE ${ev.before.ate_rmse_m.toFixed(3)} → ${ev.after.ate_rmse_m.toFixed(3)} m；最大历史节点修正 ${ev.max_historical_correction_m.toFixed(3)} m。`;let paths=[ev.before_path.xyz,ev.after_path.xyz],all=paths.flat(),xs=all.map(p=>p[0]),ys=all.map(p=>p[1]),x0=Math.min(...xs),y0=Math.min(...ys),span=Math.max(Math.max(...xs)-x0,Math.max(...ys)-y0,1),sc=260/span;paths.forEach((path,k)=>{ex.strokeStyle=k?'#65edb8':'#ffb25a';ex.lineWidth=2;ex.beginPath();path.forEach((p,i)=>{let x=ec.width/2+(p[0]-x0-span/2)*sc,y=280-(p[1]-y0)*sc;i?ex.lineTo(x,y):ex.moveTo(x,y)});ex.stroke()})}else{document.getElementById('event').textContent='没有首次有效回环事件；该案例不得作为成功回环证据。'}
document.getElementById('evidence').textContent=JSON.stringify({states:m.lifecycle_states,physical_stops:m.physical_stops,gravity_links:m.gravity_links,loop_recheck:m.loop_recheck,revisit_alignment:m.optimized_alignment,false_candidate:m.false_candidate,dynamic_residue:m.dynamic_residue},null,2);document.getElementById('checks').textContent=JSON.stringify(m.checks,null,2);reset();}
cv.onpointerdown=e=>{drag=[e.clientX,e.clientY];cv.setPointerCapture(e.pointerId)};cv.onpointerup=()=>drag=null;cv.onpointermove=e=>{if(!drag)return;yaw+=(e.clientX-drag[0])*.008;pitch=Math.max(.1,Math.min(1.55,pitch+(e.clientY-drag[1])*.008));drag=[e.clientX,e.clientY];draw()};cv.onwheel=e=>{e.preventDefault();zoom=Math.max(.25,Math.min(8,zoom*Math.exp(-e.deltaY*.001)));draw()};
sel.onchange=update;mode.onchange=draw;slider.oninput=draw;document.getElementById('reset').onclick=reset;for(let id of ['cloud','loops','prior'])document.getElementById(id).onchange=draw;update();
</script></html>'''
    rviz='<details><summary>真实 RViz 窗口复核（最终显示配置）</summary><img src="rviz_verified.png" style="max-width:100%;height:auto" alt="实际三维地图、回访轨迹和正常显示状态"></details>' if (out/'rviz_verified.png').exists() else ''
    page=page.replace('RVIZ_PREVIEW',rviz).replace('CHECKS',checks).replace('DATA',json.dumps(data,separators=(',',':')).replace('<','\\u003c')).replace('FILES',json.dumps(links)).replace('SUMMARY',json.dumps({k:v for k,v in summary.items() if k!='cases'},ensure_ascii=False))
    (out/'index.html').write_text(page);return out/'index.html'
